#include<bits/stdc++.h>
#define fr(i,a,b) for(int i(a),end##i(b);i<=end##i;i++)
#define fd(i,a,b) for(int i(a),end##i(b);i>=end##i;i--)
using namespace std;
const int maxn=500+5;
int n,m,mod;
int upd(const int &x){
	if(x<0)return x+mod;
	if(x>=mod)return x-mod;
	return x;
}
void add(int &x,const int &y){
	x=upd(x+y);
}
int ksm(int x,int k){
	int ans=1;
	while(k){
		if(k&1)ans=1ll*ans*x%mod;
		x=1ll*x*x%mod;
		k>>=1;
	}
	return ans;
}
int jc[maxn<<2],inv[maxn<<2];
void init(int n){
	jc[0]=1;
	fr(i,1,n)jc[i]=1ll*jc[i-1]*i%mod;
	inv[n]=ksm(jc[n],mod-2);
	fd(i,n-1,0)inv[i]=1ll*inv[i+1]*(i+1)%mod;	
}
int C(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*jc[n]*inv[n-m]%mod*inv[m]%mod;
}
vector<int> f,g;
int S(int n){
	return n*(n+1)/2;
}
vector<int> operator *(const vector<int> &A ,const vector<int> &B){
	vector<int> C(A.size()+B.size()-1);
	fr(i,0,A.size()-1)fr(j,0,B.size()-1)add(C[i+j],1ll*A[i]*B[j]%mod);
	return C;
}
int G(int n,int m){
	return C(m+n-1,n-1);	
}
int main(){
#ifdef pig
	freopen("1439D.in","r",stdin);
	freopen("1439D.out","w",stdout);
#endif
	cin>>m>>n>>mod;
	init(m<<1);
	f.resize(n+1);g.resize(n+1);
	f[0]=1;
	fr(i,1,n){
		fr(j,0,i-1)add(f[i],1ll*f[j]*f[i-1-j]%mod*C(i-1,j)%mod);
		f[i]=1ll*f[i]*(i+1)%mod;
	}
	fr(i,1,n){
		fr(j,0,i-1)add(g[i],(2ll*f[j]*g[i-1-j]%mod*C(i-1,j)%mod*(i+1)%mod+1ll*C(i-1,j)*(S(j)+S(i-1-j))%mod*f[j]%mod*f[i-1-j]%mod)%mod);
	}
	//cout<<g[n]<<'\n';
	//fr(i,0,n)printf("%d ",g[i]);printf("\n");
	//fr(i,0,n)printf("%d ",f[i]);printf("\n");
	f[0]=0;
	fr(i,0,n)g[i]=1ll*g[i]*inv[i]%mod;
	fr(i,0,n)f[i]=1ll*f[i]*inv[i]%mod;
	int ans=0;
	fr(i,1,m-n+1){
	//printf("g:=");fr(j,0,n)printf("%d ",g[j]);printf("\n");
		//printf("%lld %d\n",1ll*g[n]*jc[n]%mod,G(i+1,m-n-i+1));
		add(ans,1ll*g[n]*G(i+1,m-n-i+1)%mod*jc[n]%mod*i%mod);		
		g=g*f;g.resize(n+1);
	}
	cout<<ans;
	return 0;
}

